use super::*;

/// Does a top-level `function_item` node carry a `#[test]` / `#[cfg(test)]` attribute? Production leaves
/// never do; a rare top-level test fn (most live inside `#[cfg(test)] mod tests`, which is a `mod_item`
/// this walk never descends) must not be counted.
pub(crate) fn is_test_attributed(node: Node, src: &[u8]) -> bool {
    let mut sib = node.prev_sibling();
    while let Some(s) = sib {
        if s.kind() == "attribute_item" {
            let t = s.utf8_text(src).unwrap_or("");
            if t.contains("test") || t.contains("cfg(test)") {
                return true;
            }
            sib = s.prev_sibling();
            continue;
        }
        // line/block comments and empty lines sit between an attribute and its item; keep scanning past
        // them, but stop at the previous real item.
        if s.kind() == "line_comment" || s.kind() == "block_comment" {
            sib = s.prev_sibling();
            continue;
        }
        break;
    }
    false
}
